SELECT a.TRD_DATE AS `交易日期`, b.INDX_CNAME AS `指数名称`, b.INDX_CODE AS `指数代码`, ROUND(a.PB, 2) AS `市净率(倍)`, ROUND(a.PE, 2) AS `市盈率(倍)`, ROUND(a.EPS, 3) AS `每股收益(元)`, ROUND(a.SUM_TCAP/100000000, 1) AS `总市值(亿)`, ROUND(a.SUM_MKTCAP/100000000, 1) AS `流通市值(亿)` FROM ANA_INDX_VAL_IDX a JOIN GET_INDX_GEN_INFO b ON a.INNER_CODE = b.INNER_CODE WHERE b.INDX_CODE = '000852' AND b.USE_STATUS = '使用' AND b.ISVALID = 1 AND a.ISVALID = 1 AND a.TRD_DATE = (SELECT MAX(TRD_DATE) FROM ANA_INDX_VAL_IDX WHERE INNER_CODE = b.INNER_CODE AND TRD_DATE <= '2026-09-02');
